    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = br.readLine().split(" ");
        int n = Integer.parseInt(parts[0]);
        int m = Integer.parseInt(parts[1]);

        NumberTheory.Mod998 mod = new NumberTheory.Mod998();
        mod.fInv(n + m);

        long phaseSize = 1;
        long p = 1;
        for (int i = 0; p != 0; i++) {
            p = mod.mult(p, n - i, mod.smallInv(n + m - i));
            phaseSize = mod.add(phaseSize, p);
        }

        long answer = 0;
        for (int k = 1; k <= n; k++) {
            long term = mod.mult(mod.ncr(n, k), m + k, mod.smallInv(k), phaseSize);
            if (k % 2 == 1)
                answer = mod.add(answer, term);
            else
                answer = mod.subtract(answer, term);
        }
        System.out.println(answer);
    }

    static class NumberTheory {
        static class Mod998 extends NumberTheory.Modulus<Mod998> {
            public long modulus() {
                return 998_244_353L;
            }
        }
